  def icon(name, size: 16, css_class: "icon", **html_attrs)
    inner = ICONS[name.to_s]
    return "".html_safe unless inner

    tag.svg(
      inner.html_safe,
      xmlns: "http://www.w3.org/2000/svg",
      width: size,
      height: size,
      viewBox: "0 0 24 24",
      fill: "none",
      stroke: "currentColor",
      "stroke-width": "2",
      "stroke-linecap": "round",
      "stroke-linejoin": "round",
      class: [ "icon", css_class ].uniq.join(" "),
      "aria-hidden": "true",
      **html_attrs
    )
  end

  # A small help glyph with a hover/focus tooltip describing a field (CSS tooltip via
  # `.hint::after` reading data-tip — native `title` was unreliable).
  def hint(text)
    tag.span(icon("circle-help", size: 13), class: "hint", tabindex: 0,
             role: "img", "aria-label": text, data: { tip: text })
  end
